rows.vgi.example_queries:
SELECT s.frame[1].function AS fn, sum(s.value[2]) AS cpu_ns FROM glob('/profiles/*.pb.gz') f, pprof.main.stacks(f.path) s WHERE s.error IS NULL GROUP BY 1 ORDER BY 2 DESC LIMIT 20;
SELECT * FROM pprof.main.meta('cpu.pb.gz');
SELECT sample_id, frame[1].function AS leaf, value FROM pprof.main.stacks('cpu.pb.gz') WHERE error IS NULL;
SELECT mapping_id, filename, build_id FROM pprof.main.mappings('native.pb.gz') WHERE build_id IS NOT NULL;
